class StopIfEmpty extends Rule<String> {
  const StopIfEmpty({super.message});

  @override
  bool get runOnNull => true;

  @override
  String? apply(String? value, ValidationState state) {
    if (value == null || value.isEmpty) {
      state.addError(
        ValidationError(
